package com.example.service

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import com.zaxxer.hikari.HikariConfig
import com.zaxxer.hikari.HikariDataSource
import java.sql.Connection
import java.sql.PreparedStatement
import kotlinx.coroutines.*
import java.util.concurrent.atomic.AtomicReference
import sun.misc.Signal
import sun.misc.SignalHandler

object DatabasePool {
    private val currentDataSource = AtomicReference<HikariDataSource?>(null)
    private var pendingRotation: HikariDataSource? = null
    @Volatile var rotationInProgress = false

    fun init(jdbcUrl: String, user: String, password: String) {
        val config = HikariConfig().apply {
            this.jdbcUrl = jdbcUrl
            this.username = user
            this.password = password
            maximumPoolSize = 20
            minimumIdle = 5
            connectionTimeout = 3000
            // Using prepared statements through pgBouncer
            addDataSourceProperty("prepareThreshold", "5")
            addDataSourceProperty("preparedStatementCacheQueries", "256")
        }
        currentDataSource.set(HikariDataSource(config))
    }

    fun getConnection(): Connection {
        return currentDataSource.get()?.connection
            ?: throw IllegalStateException("DataSource not initialized")
    }

    // Called during credential rotation signal
    fun beginRotation(newUrl: String, newUser: String, newPass: String) {
        rotationInProgress = true
        val config = HikariConfig().apply {
            jdbcUrl = newUrl
            username = newUser
            password = newPass
            maximumPoolSize = 20
            minimumIdle = 5
        }
        pendingRotation = HikariDataSource(config)
    }

    fun commitRotation() {
        val old = currentDataSource.getAndSet(pendingRotation)
        pendingRotation = null
        rotationInProgress = false
        old?.close()
    }
}

// Signal handler for credential rotation - SIGUSR1 triggers rotation
class RotationSignalHandler : SignalHandler {
    override fun handle(sig: Signal?) {
        // Race condition: reads config file during signal, non-reentrant
        val configLines = java.io.File("/etc/service/db-credentials.conf").readLines()
        val url = configLines.find { it.startsWith("url=") }?.substringAfter("=") ?: return
        val user = configLines.find { it.startsWith("user=") }?.substringAfter("=") ?: return
        val pass = configLines.find { it.startsWith("pass=") }?.substringAfter("=") ?: return
        DatabasePool.beginRotation(url, user, pass)
        // Simulated delay - window for race
        Thread.sleep(100)
        DatabasePool.commitRotation()
    }
}

fun Application.module() {
    routing {
        get("/api/users/search") {
            val searchTerm = call.request.queryParameters["q"] ?: ""
            val sortField = call.request.queryParameters["sort"] ?: "created_at"
            val order = call.request.queryParameters["order"] ?: "DESC"

            // Parameterized query for search term (safe)
            // BUT sort field and order are interpolated (vulnerable to SQLi)
            val query = "SELECT id, username, email, created_at FROM users " +
                "WHERE username ILIKE ? OR email ILIKE ? " +
                "ORDER BY $sortField $order LIMIT 50"

            val results = mutableListOf<Map<String, Any?>>()

            DatabasePool.getConnection().use { conn ->
                conn.prepareStatement(query).use { stmt ->
                    stmt.setString(1, "%$searchTerm%")
                    stmt.setString(2, "%$searchTerm%")
                    val rs = stmt.executeQuery()
                    while (rs.next()) {
                        results.add(mapOf(
                            "id" to rs.getInt("id"),
                            "username" to rs.getString("username"),
                            "email" to rs.getString("email"),
                            "created_at" to rs.getString("created_at")
                        ))
                    }
                }
            }
            call.respond(results)
        }

        get("/api/users/{id}") {
            val userId = call.parameters["id"]?.toIntOrNull()
                ?: return@get call.respond(HttpStatusCode.BadRequest, "Invalid ID")

            DatabasePool.getConnection().use { conn ->
                conn.prepareStatement("SELECT id, username, email FROM users WHERE id = ?").use { stmt ->
                    stmt.setInt(1, userId)
                    val rs = stmt.executeQuery()
                    if (rs.next()) {
                        call.respond(mapOf(
                            "id" to rs.getInt("id"),
                            "username" to rs.getString("username"),
                            "email" to rs.getString("email")
                        ))
                    } else {
                        call.respond(HttpStatusCode.NotFound, "User not found")
                    }
                }
            }
        }
    }
}

fun main() {
    Signal.handle(Signal("USR1"), RotationSignalHandler())
    DatabasePool.init(
        System.getenv("DB_URL") ?: "jdbc:postgresql://pgbouncer:6432/appdb",
        System.getenv("DB_USER") ?: "app_service",
        System.getenv("DB_PASS") ?: "changeme"
    )
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}
